import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz the deciding parameters that are forwarded to initialize; the property:
    // "first call to initialize(...) should succeed and set initialized == true"
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep feeRate in full uint16 range but the contract reverts if >5000, so allow all values
        // no tight vm.assume to avoid excluding counterexamples

        // Call initialize and observe whether it succeeds and whether initialized becomes true.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract: the first call to initialize should succeed (ok == true) and set initialized() == true.
        // Mutant: inverts the initial check so it reverts when not initialized, causing ok==false or initialized==false.
        // Assert the general rule: either the call succeeded and initialized() is true.
        // This single assert must hold for the reference for all inputs and fail for the mutant for some inputs.
        assertTrue(ok && c.initialized());
